procedure.step:
      If the path is ambiguous or doesn't suggest a clear name:

// ? NO CLEAR NAME — derived from admin/misc/x.blade.php
export default function AdminMiscX(): JSX.Element { /* … */ }

      Wrap the component in React.memo using a named function expression:

import { memo, JSX } from "react";

interface ConfirmModalProps {
  open: boolean;
  onClose: () => void;
  message: string;
}

const ConfirmModal = memo(function ConfirmModal({
  open,
  onClose,
  message,
}: ConfirmModalProps): JSX.Element | null {
  if (!open) return null;
  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <p>{message}</p>
        <button onClick={onClose}>Close</button>
      </div>
    </div>
  );
});

export default ConfirmModal;

      Define the modal component, rendering children into document.body:

import { JSX, ReactNode } from "react";
import { createPortal } from "react-dom";

interface ModalProps {
  open: boolean;
  onClose: () => void;
  children: ReactNode;
}

export default function Modal({ open, onClose, children }: ModalProps): JSX.Element | null {
  if (!open) return null;
  return createPortal(
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50" onClick={onClose}>
      <div className="bg-white rounded-lg p-6 max-w-md" onClick={e => e.stopPropagation()}>
        {children}
      </div>
    </div>,
    document.body,
  );
}

      Get the queryClient from useQueryClient():

import { useQueryClient } from "@tanstack/react-query";
const queryClient = useQueryClient();

      Call invalidateQueries with a queryKey dictionary — never a plain string:

// ✅ Correct
queryClient.invalidateQueries({ queryKey: ["tasks"] });

// ❌ Wrong
queryClient.invalidateQueries("tasks");
queryClient.invalidateQueries(["tasks"]);

      Create or reuse a fallback component:

function ErrorFallback({ error, resetErrorBoundary }: {
  error: Error;
  resetErrorBoundary: () => void;
}): JSX.Element {
  return (
    <div className="p-8 text-center">
      <h2 className="text-xl font-bold text-red-600">Something went wrong</h2>
      <pre className="mt-2 text-sm text-gray-600">{error.message}</pre>
      <button className="mt-4 btn" onClick={resetErrorBoundary}>Try again</button>
    </div>
  );
}

Wrap the target component tree:
import { ErrorBoundary } from "react-error-boundary";
<ErrorBoundary FallbackComponent={ErrorFallback} onReset={() => { /* reset state */ }}> <TaskDashboard /> </ErrorBoundary>
